import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { CartService } from '../../services/cart.service';
import { CartItem } from '../../models/cart-item';

@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.css']
})
export class CartComponent {
  constructor(public cart: CartService, private router: Router) {}

  get items(): CartItem[] { return this.cart.cartItems; }

  updateQty(productId: number, qty: number): void {
    this.cart.updateQuantity(productId, qty);
  }

  remove(productId: number): void {
    this.cart.removeFromCart(productId);
  }

  checkout(): void {
    this.router.navigate(['/checkout']);
  }

  continueShopping(): void {
    this.router.navigate(['/products']);
  }
}
<div class="cart-page">
  <h1 class="cart-title">Shopping Cart</h1>

  <div class="cart-layout" *ngIf="items.length > 0; else emptyCart">
    <div class="cart-items">
      <div class="cart-item" *ngFor="let item of items">
        <img [src]="item.product.imageUrl" [alt]="item.product.name" class="item-img" />
        <div class="item-info">
          <h3 class="item-name">{{ item.product.name }}</h3>
          <p class="item-category">{{ item.product.category }}</p>
          <span class="item-price">₹{{ item.product.price | number }}</span>
        </div>
        <div class="item-qty">
          <button (click)="updateQty(item.product.id, item.quantity - 1)">−</button>
          <span>{{ item.quantity }}</span>
          <button (click)="updateQty(item.product.id, item.quantity + 1)">+</button>
        </div>
        <div class="item-subtotal">₹{{ (item.product.price * item.quantity) | number }}</div>
        <button class="remove-btn" (click)="remove(item.product.id)" title="Remove">✕</button>
      </div>
    </div>

    <div class="cart-summary">
      <h2>Order Summary</h2>
      <div class="summary-row">
        <span>Items ({{ cart.itemCount }})</span>
        <span>₹{{ cart.total | number }}</span>
      </div>
      <div class="summary-row">
        <span>Shipping</span>
        <span>{{ cart.total >= 500 ? 'FREE' : '₹49' }}</span>
      </div>
      <div class="summary-divider"></div>
      <div class="summary-row total">
        <span>Total</span>
        <span>₹{{ (cart.total >= 500 ? cart.total : cart.total + 49) | number }}</span>
      </div>
      <button class="checkout-btn" (click)="checkout()">Proceed to Checkout</button>
      <button class="continue-btn" (click)="continueShopping()">← Continue Shopping</button>
    </div>
  </div>

  <ng-template #emptyCart>
    <div class="empty-cart">
      <div class="empty-icon">🛒</div>
      <h2>Your cart is empty</h2>
      <p>Looks like you haven't added anything yet.</p>
      <button class="continue-btn" (click)="continueShopping()">Start Shopping</button>
    </div>
  </ng-template>
</div>
